-- 既存テーブル削除（完全リセット用。運用時は必要に応じてバックアップ推奨）
DROP TABLE IF EXISTS member.generation_roles CASCADE;
DROP TABLE IF EXISTS member.team_leaders CASCADE;
DROP TABLE IF EXISTS member.member_team_relations CASCADE;
DROP TABLE IF EXISTS member.teams CASCADE;
DROP TABLE IF EXISTS member.members CASCADE;
DROP SCHEMA IF EXISTS member CASCADE;

-- スキーマ作成
CREATE SCHEMA IF NOT EXISTS member;

-- Grant usage to necessary roles
grant usage on schema member to postgres, anon, authenticated, service_role;

-- Set default grants for new tables in the member schema
alter default privileges in schema member grant all on tables to postgres, anon, authenticated, service_role;
alter default privileges in schema member grant all on functions to postgres, anon, authenticated, service_role;
alter default privileges in schema member grant all on sequences to postgres, anon, authenticated, service_role;


-- 部員テーブル（Supabase AuthユーザーIDがPK&FK、管理項目付き）
CREATE TABLE member.members (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    display_name TEXT NOT NULL,
    status INTEGER NOT NULL,                                     -- 区分（0=中等部, 1=高等部, 2=OB）
    generation INTEGER NOT NULL,                                 -- 期生
    student_number TEXT,                                         -- 学籍番号
    discord_id TEXT UNIQUE NOT NULL,                            -- Discord公式API/Bot用UID
    is_admin BOOLEAN NOT NULL DEFAULT FALSE,                     -- 管理者フラグ
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,    -- 登録日時
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at TIMESTAMPTZ                                       -- 論理削除
);

-- 班テーブル
CREATE TABLE member.teams (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    discord_role_id TEXT
);

-- 部員⇔班の関係（多対多）
CREATE TABLE member.member_team_relations (
    member_id UUID NOT NULL REFERENCES member.members(id) ON DELETE CASCADE,
    team_id INTEGER NOT NULL REFERENCES member.teams(id) ON DELETE CASCADE,
    PRIMARY KEY (member_id) -- 1人1班制
);

-- 班長テーブル（複数班長対応。1班に複数人指定OK）
CREATE TABLE member.team_leaders (
    team_id INTEGER NOT NULL REFERENCES member.teams(id) ON DELETE CASCADE,
    member_id UUID NOT NULL REFERENCES member.members(id) ON DELETE CASCADE,
    PRIMARY KEY (team_id, member_id)
);

-- 期生⇔Discord Role対応テーブル
CREATE TABLE member.generation_roles (
    generation INTEGER PRIMARY KEY,           -- 期生番号
    discord_role_id TEXT NOT NULL UNIQUE
);

-- インデックス（検索高速化）
CREATE INDEX ON member.members(status);
CREATE INDEX ON member.members(discord_id);
CREATE INDEX ON member.members(is_admin);
CREATE INDEX ON member.teams(discord_role_id);
CREATE INDEX ON member.member_team_relations(member_id);
CREATE INDEX ON member.member_team_relations(team_id);
CREATE INDEX ON member.team_leaders(team_id);
CREATE INDEX ON member.team_leaders(member_id);
CREATE INDEX ON member.generation_roles(discord_role_id);

-- Enable RLS
alter table member.members enable row level security;
alter table member.teams enable row level security;
alter table member.member_team_relations enable row level security;
alter table member.team_leaders enable row level security;
alter table member.generation_roles enable row level security;

-- Policies for member.members
create policy "Allow all access to service_role" on member.members for all to service_role using (true) with check (true);
create policy "Allow read access to authenticated users" on member.members for select to authenticated using (true);
create policy "Allow user to update their own profile" on member.members for update to authenticated using (auth.uid() = id);

-- Policies for member.teams
create policy "Allow all access to service_role" on member.teams for all to service_role using (true) with check (true);
create policy "Allow read access to authenticated users" on member.teams for select to authenticated using (true);

-- Policies for member.member_team_relations
create policy "Allow all access to service_role" on member.member_team_relations for all to service_role using (true) with check (true);
create policy "Allow read access to authenticated users" on member.member_team_relations for select to authenticated using (true);

-- Policies for other tables (assuming less frequent access, admin only)
create policy "Allow all access to service_role on team_leaders" on member.team_leaders for all to service_role using (true) with check (true);
create policy "Allow all access to service_role on generation_roles" on member.generation_roles for all to service_role using (true) with check (true);

-- Create the attendance schema
create schema if not exists attendance;

-- Grant usage to necessary roles
grant usage on schema attendance to postgres, anon, authenticated, service_role;

-- Set default grants for new tables in the attendance schema
alter default privileges in schema attendance grant all on tables to postgres, anon, authenticated, service_role;
alter default privileges in schema attendance grant all on functions to postgres, anon, authenticated, service_role;
alter default privileges in schema attendance grant all on sequences to postgres, anon, authenticated, service_role;

--
-- attendance.users TABLE
--
create table attendance.users (
    supabase_auth_user_id uuid not null primary key references member.members(supabase_auth_user_id) on delete cascade,
    card_id character varying not null unique,
    created_at timestamp with time zone not null default now(),
    updated_at timestamp with time zone not null default now()
);
alter table attendance.users enable row level security;

create policy "Allow all access to service_role" on attendance.users for all to service_role using (true) with check (true);
create policy "Allow read access to authenticated users" on attendance.users for select to authenticated using (true);


--
-- attendance.attendances TABLE
--
create table attendance.attendances (
    id uuid not null default gen_random_uuid() primary key,
    user_id uuid not null references attendance.users (supabase_auth_user_id) on delete cascade,
    card_id character varying not null,
    "type" character varying not null,
    "timestamp" timestamp with time zone not null default now(),
    date date not null default (now() at time zone 'utc'::text),
    created_at timestamp with time zone not null default now()
);
alter table attendance.attendances enable row level security;
create index idx_attendances_date_user on attendance.attendances using btree (date, user_id);
create index idx_attendances_user_timestamp on attendance.attendances using btree (user_id, "timestamp");

create policy "Allow all access to service_role" on attendance.attendances for all to service_role using (true) with check (true);
create policy "Allow read access to user for their own records" on attendance.attendances for select to authenticated using ((select auth.uid()) = user_id);


--
-- attendance.temp_registrations TABLE
--
create table attendance.temp_registrations (
    id uuid not null default gen_random_uuid() primary key,
    card_id character varying not null,
    qr_token character varying not null,
    expires_at timestamp with time zone not null,
    is_used boolean not null default false,
    accessed_at timestamp with time zone,
    created_at timestamp with time zone not null default now()
);
alter table attendance.temp_registrations enable row level security;

create unique index temp_registrations_card_id_is_used_expires_at_idx on attendance.temp_registrations (card_id, is_used, expires_at);
create unique index temp_registrations_qr_token_key on attendance.temp_registrations using btree (qr_token);
create index idx_temp_registrations_expires on attendance.temp_registrations using btree (expires_at);

create policy "Allow all access to service_role" on attendance.temp_registrations for all to service_role using (true) with check (true);
create policy "Allow read access for all users" on attendance.temp_registrations for select using (true);


--
-- attendance.daily_logout_logs TABLE
--
create table attendance.daily_logout_logs (
    id uuid not null default gen_random_uuid() primary key,
    executed_at timestamp with time zone not null default now(),
    affected_count integer not null,
    status character varying not null
);
alter table attendance.daily_logout_logs enable row level security;
create policy "Allow all access to service_role" on attendance.daily_logout_logs for all to service_role using (true) with check (true);


--
-- Realtime Publication Setup
--
-- temp_registrations テーブルをRealtimeで監視可能にする（QRコード読み取り検知用）
alter publication supabase_realtime add table attendance.temp_registrations;

-- Security fix: Enforce least-privilege on all schemas
--
-- Problem found in production:
--   1. member schema: RLS was disabled, allowing anon to read/write all member data
--   2. Both schemas: ALTER DEFAULT PRIVILEGES granted ALL to anon (overly broad)
--   3. attendance tables: anon had INSERT/UPDATE/DELETE in addition to SELECT
--
-- This migration:
--   - Re-enables RLS on all tables (FORCE for extra safety)
--   - Revokes excess anon grants; anon only gets what kiosk strictly needs:
--       * EXECUTE on attendance.record_attendance_by_card (direct RPC from kiosk)
--       * SELECT on attendance.temp_registrations (Realtime QR channel subscription)
--   - Adds missing authenticated READ policies on team_leaders / generation_roles


-- ================================================================
-- MEMBER SCHEMA: Enable RLS and revoke anon direct table access
-- ================================================================

-- Re-enable RLS (idempotent)
ALTER TABLE member.members ENABLE ROW LEVEL SECURITY;
ALTER TABLE member.teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE member.member_team_relations ENABLE ROW LEVEL SECURITY;
ALTER TABLE member.team_leaders ENABLE ROW LEVEL SECURITY;
ALTER TABLE member.generation_roles ENABLE ROW LEVEL SECURITY;

-- Force RLS even for table owner (prevents accidental bypass via service key outside policies)
ALTER TABLE member.members FORCE ROW LEVEL SECURITY;
ALTER TABLE member.teams FORCE ROW LEVEL SECURITY;
ALTER TABLE member.member_team_relations FORCE ROW LEVEL SECURITY;
ALTER TABLE member.team_leaders FORCE ROW LEVEL SECURITY;
ALTER TABLE member.generation_roles FORCE ROW LEVEL SECURITY;

-- Revoke all direct anon access on member tables
-- (anon has no business reading member data directly)
REVOKE ALL ON member.members FROM anon;
REVOKE ALL ON member.teams FROM anon;
REVOKE ALL ON member.member_team_relations FROM anon;
REVOKE ALL ON member.team_leaders FROM anon;
REVOKE ALL ON member.generation_roles FROM anon;

-- Fix default privileges so future tables don't auto-grant anon
ALTER DEFAULT PRIVILEGES IN SCHEMA member REVOKE ALL ON TABLES FROM anon;

-- Add missing READ policies for authenticated users on team_leaders / generation_roles
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'member' AND tablename = 'team_leaders'
      AND policyname = 'Allow read access to authenticated users on team_leaders'
  ) THEN
    CREATE POLICY "Allow read access to authenticated users on team_leaders"
      ON member.team_leaders FOR SELECT TO authenticated USING (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'member' AND tablename = 'generation_roles'
      AND policyname = 'Allow read access to authenticated users on generation_roles'
  ) THEN
    CREATE POLICY "Allow read access to authenticated users on generation_roles"
      ON member.generation_roles FOR SELECT TO authenticated USING (true);
  END IF;
END $$;


-- ================================================================
-- ATTENDANCE SCHEMA: Tighten anon access
-- ================================================================

-- attendances: anon should have NO direct access
-- (authenticated users can read their own records via RLS policy)
REVOKE ALL ON attendance.attendances FROM anon;

-- attendance.users: anon should have NO direct access
-- (the SECURITY DEFINER RPC accesses this internally)
REVOKE ALL ON attendance.users FROM anon;

-- daily_logout_logs: anon should have NO access
REVOKE ALL ON attendance.daily_logout_logs FROM anon;

-- temp_registrations: revoke write access, keep SELECT
-- SELECT is required for the kiosk Realtime subscription (QR scan detection)
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON attendance.temp_registrations FROM anon;
-- GRANT SELECT remains (already present via default privileges + existing policy)
GRANT SELECT ON attendance.temp_registrations TO anon;

-- Fix default privileges so future attendance tables don't auto-grant anon
ALTER DEFAULT PRIVILEGES IN SCHEMA attendance REVOKE ALL ON TABLES FROM anon;

-- Force RLS on attendance tables
ALTER TABLE attendance.attendances FORCE ROW LEVEL SECURITY;
ALTER TABLE attendance.users FORCE ROW LEVEL SECURITY;
ALTER TABLE attendance.temp_registrations FORCE ROW LEVEL SECURITY;
ALTER TABLE attendance.daily_logout_logs FORCE ROW LEVEL SECURITY;


-- ================================================================
-- RPC: Ensure kiosk can still call the SECURITY DEFINER function
-- ================================================================
GRANT EXECUTE ON FUNCTION attendance.record_attendance_by_card(text) TO anon;

-- OAuth 2.0 Schema for STEM-system
-- 複数クライアントアプリケーションからのOAuth認証をサポート

-- oauth スキーマ作成
CREATE SCHEMA IF NOT EXISTS oauth;

-- OAuth クライアントアプリケーション
-- 管理者が登録するクライアントアプリ（kintai-v3など）
CREATE TABLE oauth.applications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,                    -- アプリ名（例: "Kintai System"）
  client_id TEXT UNIQUE NOT NULL,        -- ランダム生成されたクライアントID
  client_secret_hash TEXT NOT NULL,      -- bcrypt ハッシュ化されたシークレット
  redirect_uris TEXT[] NOT NULL,         -- 許可されたリダイレクトURI配列
  created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, -- 作成者（管理者）
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 認可コード（短命、10分で期限切れ）
-- Authorization Code Flowで使用される一時的なコード
CREATE TABLE oauth.authorization_codes (
  code TEXT PRIMARY KEY,                 -- ランダム生成されたコード
  application_id UUID NOT NULL REFERENCES oauth.applications(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  redirect_uri TEXT NOT NULL,            -- コード発行時のリダイレクトURI
  code_challenge TEXT,                   -- PKCE用のチャレンジ
  code_challenge_method TEXT,            -- PKCE メソッド（"S256"）
  scope TEXT NOT NULL DEFAULT 'openid profile',
  expires_at TIMESTAMPTZ NOT NULL,       -- 10分後に設定
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ユーザーの連携承認記録
-- ユーザーがどのアプリを承認したかを記録
CREATE TABLE oauth.user_consents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  application_id UUID NOT NULL REFERENCES oauth.applications(id) ON DELETE CASCADE,
  scope TEXT NOT NULL,
  granted_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, application_id)        -- 1ユーザー1アプリ1承認
);

-- インデックス（パフォーマンス最適化）
CREATE INDEX idx_auth_codes_expires ON oauth.authorization_codes(expires_at);
CREATE INDEX idx_auth_codes_user ON oauth.authorization_codes(user_id);
CREATE INDEX idx_auth_codes_app ON oauth.authorization_codes(application_id);
CREATE INDEX idx_user_consents_user ON oauth.user_consents(user_id);
CREATE INDEX idx_user_consents_app ON oauth.user_consents(application_id);
CREATE INDEX idx_applications_client_id ON oauth.applications(client_id);

-- RLS (Row Level Security) 有効化
ALTER TABLE oauth.applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth.authorization_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth.user_consents ENABLE ROW LEVEL SECURITY;

-- RLS ポリシー: oauth.applications
-- 管理者のみがアプリケーションを管理できる
CREATE POLICY "管理者のみアプリを作成可能" ON oauth.applications
  FOR INSERT WITH CHECK (
    EXISTS (SELECT 1 FROM member.members WHERE id = auth.uid() AND is_admin = true)
  );

CREATE POLICY "管理者のみアプリを参照可能" ON oauth.applications
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM member.members WHERE id = auth.uid() AND is_admin = true)
  );

CREATE POLICY "管理者のみアプリを削除可能" ON oauth.applications
  FOR DELETE USING (
    EXISTS (SELECT 1 FROM member.members WHERE id = auth.uid() AND is_admin = true)
  );

CREATE POLICY "管理者のみアプリを更新可能" ON oauth.applications
  FOR UPDATE USING (
    EXISTS (SELECT 1 FROM member.members WHERE id = auth.uid() AND is_admin = true)
  );

-- RLS ポリシー: oauth.authorization_codes
-- 認可コードはサーバーサイドからのみアクセス（RLSなし・サービスロールキー使用）
-- 安全のため全アクセスを拒否（アプリケーションコードから直接操作）
CREATE POLICY "認可コードは直接アクセス不可" ON oauth.authorization_codes
  FOR ALL USING (false);

-- RLS ポリシー: oauth.user_consents
-- ユーザーは自分の承認記録のみ参照・削除可能
CREATE POLICY "自分の承認記録のみ参照可能" ON oauth.user_consents
  FOR SELECT USING (user_id = auth.uid());

CREATE POLICY "自分の承認記録のみ削除可能" ON oauth.user_consents
  FOR DELETE USING (user_id = auth.uid());

-- システムが承認記録を作成（サーバーサイドから）
CREATE POLICY "システムが承認記録を作成" ON oauth.user_consents
  FOR INSERT WITH CHECK (true);

-- 期限切れ認可コードの自動削除関数
CREATE OR REPLACE FUNCTION oauth.cleanup_expired_codes()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  DELETE FROM oauth.authorization_codes
  WHERE expires_at < NOW();
END;
$$;

-- コメント追加（ドキュメント）
COMMENT ON SCHEMA oauth IS 'OAuth 2.0 Authorization Server用スキーマ';
COMMENT ON TABLE oauth.applications IS 'OAuth クライアントアプリケーション登録';
COMMENT ON TABLE oauth.authorization_codes IS '認可コード（10分で期限切れ）';
COMMENT ON TABLE oauth.user_consents IS 'ユーザーの連携アプリ承認記録';
COMMENT ON FUNCTION oauth.cleanup_expired_codes IS '期限切れ認可コードを削除（定期実行推奨）';

-- Add display_name column to member.members (cache for Discord nickname)
ALTER TABLE member.members ADD COLUMN IF NOT EXISTS display_name text;

-- Create RPC function for single-call kiosk attendance recording
-- Called directly from browser (bypasses Vercel serverless for speed)
-- Falls back to auth.users global_name if display_name is NULL
CREATE OR REPLACE FUNCTION attendance.record_attendance_by_card(p_card_id text)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = attendance, member
AS $$
DECLARE
  v_user_id uuid;
  v_display_name text;
  v_discord_uid text;
  v_last_type text;
  v_new_type text;
  v_now timestamptz := now();
  v_date date := (v_now AT TIME ZONE 'Asia/Tokyo')::date;
BEGIN
  -- カードIDからユーザーID取得
  SELECT u.supabase_auth_user_id INTO v_user_id
  FROM attendance.users u WHERE u.card_id = p_card_id;

  IF v_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'message', '未登録のカードです。', 'user', null, 'type', null);
  END IF;

  -- メンバー情報取得（display_name + discord_uid）
  SELECT m.display_name, m.discord_uid INTO v_display_name, v_discord_uid
  FROM member.members m WHERE m.supabase_auth_user_id = v_user_id;

  -- display_nameがNULLの場合、auth.usersからglobal_nameをフォールバック
  IF v_display_name IS NULL THEN
    SELECT au.raw_user_meta_data->'custom_claims'->>'global_name'
    INTO v_display_name
    FROM auth.users au WHERE au.id = v_user_id;
  END IF;

  -- 最新出退勤取得
  SELECT a.type INTO v_last_type
  FROM attendance.attendances a WHERE a.user_id = v_user_id
  ORDER BY a.timestamp DESC LIMIT 1;

  v_new_type := CASE WHEN v_last_type = 'in' THEN 'out' ELSE 'in' END;

  -- 出退勤記録挿入
  INSERT INTO attendance.attendances (user_id, card_id, type, timestamp, date)
  VALUES (v_user_id, p_card_id, v_new_type, v_now, v_date);

  RETURN json_build_object(
    'success', true,
    'message', CASE WHEN v_new_type = 'in' THEN '出勤しました' ELSE '退勤しました' END,
    'user', json_build_object('display_name', v_display_name, 'discord_uid', v_discord_uid),
    'type', v_new_type
  );
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'message', '打刻処理中にエラーが発生しました: ' || SQLERRM, 'user', null, 'type', null);
END;
$$;

'use server';
import { createSupabaseServerClient } from '@/lib/supabase/server';
import { fetchMemberStatus } from '@/lib/member-status-api';
import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';

export async function GET(request: Request) {
  const origin = process.env.NEXT_PUBLIC_APP_URL!;
  const { searchParams } = new URL(request.url)
  const code = searchParams.get('code')
  const errorParam = searchParams.get('error');
  const errorDescription = searchParams.get('error_description');

  // Cookieから登録ページのパスを取得（もしあれば）
  const cookieStore = await cookies();
  const authNext = cookieStore.get('auth_next')?.value;
  const next = authNext || searchParams.get('next') || '/dashboard';

  // 使用済みCookieを削除
  if (authNext) {
    cookieStore.delete('auth_next');
  }

  console.log('[AUTH CALLBACK] ========================================');
  console.log('[AUTH CALLBACK] Timestamp:', new Date().toISOString());
  console.log('[AUTH CALLBACK] Request URL:', request.url);
  console.log('[AUTH CALLBACK] Origin:', origin);
  console.log('[AUTH CALLBACK] Next redirect:', next);
  console.log('[AUTH CALLBACK] Code present:', !!code);
  console.log('[AUTH CALLBACK] Error param:', errorParam);
  console.log('[AUTH CALLBACK] Error description:', errorDescription);
  if (code) {
    console.log('[AUTH CALLBACK] Code (first 20 chars):', code.substring(0, 20) + '...');
  }

  // OAuthプロバイダーからのエラーをチェック
  if (errorParam) {
    console.error('[AUTH CALLBACK] ❌ OAuth error from provider');
    console.error('[AUTH CALLBACK] Error:', errorParam);
    console.error('[AUTH CALLBACK] Error code:', searchParams.get('error_code'));
    console.error('[AUTH CALLBACK] Error description:', errorDescription);
    console.error('[AUTH CALLBACK] ========================================');

    // ユーザーに分かりやすいエラーメッセージを表示
    let userMessage = '認証中にエラーが発生しました。';
    if (errorDescription?.includes('Unable to exchange external code')) {
      userMessage = '認証の処理中にエラーが発生しました。時間をおいて再度お試しください。改善しない場合は管理者にお問い合わせください。';
    } else if (errorDescription) {
      userMessage = errorDescription;
    }

    return NextResponse.redirect(`${origin}/login?error=${encodeURIComponent(userMessage)}`);
  }

  if (!code) {
    console.error('[AUTH CALLBACK] No code parameter in callback URL');
    return NextResponse.redirect(`${origin}/login?error=認証コードが見つかりません。`);
  }

  const supabase = await createSupabaseServerClient();

  console.log('[AUTH CALLBACK] Attempting code exchange with Supabase...');
  // PKCEフローでコードをセッションに交換
  const { data, error } = await supabase.auth.exchangeCodeForSession(code);

  if (error) {
    console.error('[AUTH CALLBACK] ❌ Code exchange FAILED');
    console.error('[AUTH CALLBACK] Error name:', error.name);
    console.error('[AUTH CALLBACK] Error message:', error.message);
    console.error('[AUTH CALLBACK] Error status:', error.status);
    console.error('[AUTH CALLBACK] Error code:', error.code);
    console.error('[AUTH CALLBACK] Full error object:', JSON.stringify(error, null, 2));

    // PKCEエラーの場合は再ログインを促す
    if (error.message.includes('flow state')) {
      return NextResponse.redirect(`${origin}/login?error=セッションの有効期限が切れました。もう一度ログインしてください。`);
    }
    return NextResponse.redirect(`${origin}/login?error=セッションの確立に失敗しました: ${error.message}`);
  }

  console.log('[AUTH CALLBACK] ✅ Code exchange successful');

  if (!data.session || !data.user) {
    console.error('[AUTH CALLBACK] ❌ No session or user in response');
    console.error('[AUTH CALLBACK] data.session:', !!data.session);
    console.error('[AUTH CALLBACK] data.user:', !!data.user);
    return NextResponse.redirect(`${origin}/login?error=セッションの確立に失敗しました。`);
  }

  console.log('[AUTH CALLBACK] User ID:', data.user.id);
  console.log('[AUTH CALLBACK] User email:', data.user.email);
  console.log('[AUTH CALLBACK] Session expires at:', data.session.expires_at);
  console.log('[AUTH CALLBACK] User metadata:', JSON.stringify(data.user.user_metadata, null, 2));

  const discordUid = data.user.user_metadata.provider_id;
  console.log('[AUTH CALLBACK] Discord UID:', discordUid);

  if (!discordUid) {
      console.error('[AUTH CALLBACK] ❌ Discord UID not found in user metadata');
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=DiscordユーザーIDが取得できませんでした。`);
  }

  // Discord サーバー所属チェック（一時的にコメントアウト）
  /*
  const { data: memberStatus, error: apiError } = await fetchMemberStatus(discordUid);

  if (apiError) {
      console.error('Error fetching member status from API:', apiError);
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=APIとの通信中にエラーが発生しました。しばらく待ってから再度お試しください。`);
  }

  if (!memberStatus || !memberStatus.is_in_server) {
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=指定されたDiscordサーバーのメンバーではありません。`);
  }
  */

  // member.members テーブルにユーザーが登録されているかチェック
  console.log('[AUTH CALLBACK] Checking member.members table for Discord UID:', discordUid);
  const { data: memberRecord, error: memberError } = await supabase
    .schema('member')
    .from('members')
    .select('supabase_auth_user_id')
    .eq('discord_uid', discordUid)
    .single();

  if (memberError) {
    console.error('[AUTH CALLBACK] ❌ Member lookup error');
    console.error('[AUTH CALLBACK] Error code:', memberError.code);
    console.error('[AUTH CALLBACK] Error message:', memberError.message);
    console.error('[AUTH CALLBACK] Error details:', memberError.details);
    console.error('[AUTH CALLBACK] Error hint:', memberError.hint);
  }

  if (memberError || !memberRecord) {
      console.log('[AUTH CALLBACK] ❌ User not found in member.members table');
      console.log('[AUTH CALLBACK] Discord UID searched:', discordUid);
      console.log('[AUTH CALLBACK] Member record:', memberRecord);
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=not_registered`);
  }

  console.log('[AUTH CALLBACK] ✅ User found in members table');
  console.log('[AUTH CALLBACK] Member supabase_auth_user_id:', memberRecord.supabase_auth_user_id);
  console.log('[AUTH CALLBACK] Redirecting to:', next);
  console.log('[AUTH CALLBACK] ========================================');

  return NextResponse.redirect(`${origin}${next}`);
}

import { NextResponse } from 'next/server';
import { forceLogoutAll } from '@/app/actions';
import { toZonedTime } from 'date-fns-tz';

export const dynamic = 'force-dynamic';

export async function GET() {
  const timeZone = 'Asia/Tokyo';
  const now = toZonedTime(new Date(), timeZone);

  const currentHour = now.getHours();
  const currentMinute = now.getMinutes();

  // JSTの22:50から23:50までの間かチェック
  const isTimeWindowActive = 
    (currentHour === 22 && currentMinute >= 50) || 
    (currentHour === 23 && currentMinute <= 50);

  if (!isTimeWindowActive) {
    return NextResponse.json(
      { success: false, message: '現在、この機能は利用できません。JST 22:50から23:50の間のみ有効です。' },
      { status: 403 } // Forbidden
    );
  }

  try {
    const result = await forceLogoutAll();
    return NextResponse.json(result);
  } catch (error) {
    console.error('Error in force-logout-all API route:', error);
    return NextResponse.json(
      { success: false, message: 'サーバー内部でエラーが発生しました。' },
      { status: 500 }
    );
  }
}

import { type NextRequest, NextResponse } from "next/server";
import { updateSession } from "@/lib/supabase/middleware";

export async function middleware(request: NextRequest) {
  // Kiosk画面へのアクセスを保護
  if (request.nextUrl.pathname.startsWith("/kiosk")) {
    const { searchParams } = request.nextUrl;
    const token = searchParams.get("token");
    const kioskToken = process.env.KIOSK_ACCESS_TOKEN;

    if (!kioskToken) {
        console.error("KIOSK_ACCESS_TOKEN is not set on the server.");
        // 本番環境ではエラーページにリダイレクトすることを推奨
        return new NextResponse("Kiosk is not configured.", { status: 500 });
    }

    if (token !== kioskToken) {
      // トークンが不正な場合は、ページの存在を悟られないようにダッシュボードへリダイレクト
      const url = request.nextUrl.clone();
      url.pathname = "/dashboard";
      url.search = ''; // クエリパラメータをクリア
      return NextResponse.redirect(url);
    }

    // トークンが有効な場合は、そのままKioskページを表示
    return NextResponse.next();
  }

  // OAuth セッションチェック（/login と /auth/* 以外）
  const isPublicPath = request.nextUrl.pathname.startsWith('/login') || 
                       request.nextUrl.pathname.startsWith('/auth/');

  if (!isPublicPath) {
    const oauthUserId = request.cookies.get('oauth_user_id')?.value;
    const oauthToken = request.cookies.get('oauth_access_token')?.value;

    // OAuth セッションがある場合はそのまま通す
    if (oauthUserId && oauthToken) {
      return NextResponse.next();
    }

    // OAuth セッションがない場合はログインへリダイレクト
    const url = request.nextUrl.clone();
    url.pathname = "/login";
    return NextResponse.redirect(url);
  }

  // 他のすべてのルートでSupabaseのセッションを更新（後方互換性のため残す）
  return await updateSession(request);
}

