342	    .select('date, type')
343	    .eq('user_id', userId)
344	    .gte('date', formatDate(start, 'yyyy-MM-dd'))
345	    .lte('date', formatDate(end, 'yyyy-MM-dd'))
346	    .order('timestamp', { ascending: true });
347	
348	  if (error) {
349	    console.error('Error fetching monthly attendance:', error);
350	    return [];
351	  }
352	
353	  const dailyStatus: Record<string, 'in' | 'out' | 'mixed'> = {};
354	  attendances.forEach(att => {
