371	export async function getMonthlyAttendanceSummary(month: Date) {
372	  const supabase = await createSupabaseAdminClient();
373	  const start = formatDate(startOfMonth(month), 'yyyy-MM-dd');
374	  const end = formatDate(endOfMonth(month), 'yyyy-MM-dd');
375	
