377	
378	  if (error) {
379	    console.error('Error fetching monthly attendance summary:', error);
380	    return {};
381	  }
382	
383	  type DailySummary = {
384	    total: number;
385	    byTeam: Record<string, { name: string; total: number; byGeneration: Record<number, number> }>;
386	  };
387	
388	  const summary: Record<string, DailySummary> = {};
389	
390	  if (data) {
391	    for (const record of (data as any[])) {
392	        const { date, team_id, team_name, generation, count } = record;
393	        if (!date || !team_id || !team_name || count === null) continue;
394	
395	        const dateKey = formatDate(new Date(date), 'yyyy-MM-dd');
396	
397	        if (!summary[dateKey]) {
398	            summary[dateKey] = { total: 0, byTeam: {} };
399	        }
400	        
401	        if (!summary[dateKey].byTeam[team_id]) {
402	            summary[dateKey].byTeam[team_id] = { name: team_name, total: 0, byGeneration: {} };
403	        }
404	        
405	        summary[dateKey].total += count;
406	        summary[dateKey].byTeam[team_id].total += count;
407	        if(generation !== null) {
408	          summary[dateKey].byTeam[team_id].byGeneration[generation] = (summary[dateKey].byTeam[team_id].byGeneration[generation] || 0) + count;
409	        }
410	    }
411	  }
412	  return summary;
413	}
