416	export async function calculateTotalActivityTime(userId: string, days: number): Promise<number> {
417	  const supabase = await createSupabaseServerClient();
418	  const startDate = subDays(new Date(), days).toISOString();
419	
420	  const { data: attendances, error } = await supabase
421	    .schema('attendance')
422	    .from('attendances')
423	    .select('type, timestamp')
424	    .eq('user_id', userId)
425	    .gte('timestamp', startDate)
426	    .order('timestamp', { ascending: true });
427	
428	  if (error || !attendances) {
429	    console.error('Error fetching attendances for time calculation:', error);
430	    return 0;
431	  }
432	
433	  let totalSeconds = 0;
434	  let inTime: Date | null = null;
435	
436	  for (const attendance of attendances) {
437	    if (attendance.type === 'in') {
438	      inTime = new Date(attendance.timestamp);
439	    } else if (attendance.type === 'out' && inTime) {
440	      const outTime = new Date(attendance.timestamp);
441	      totalSeconds += differenceInSeconds(outTime, inTime);
442	      inTime = null; 
443	    }
444	  }
445	
446	  return totalSeconds / 3600;
447	}
