817	export async function getMonthlyTeamAttendanceStats(teamId: string, days: number): Promise<number> {
818	    const supabase = await createSupabaseAdminClient();
819	    // OB/OG（status === 2）を除外
820	    const { data: teamMembers, error: teamMembersError } = await supabase
821	        .schema('member')
822	        .from('member_team_relations')
823	        .select('member_id, members!inner(status)')
824	        .eq('team_id', teamId)
825	        .neq('members.status', 2);
826	
827	    if (teamMembersError || !teamMembers || teamMembers.length === 0) return 0;
828	    
829	    const memberIds = teamMembers.map(m => m.member_id);
830	
831	    const { data: attendanceUsers } = await supabase.schema('attendance').from('users').select('supabase_auth_user_id').in('supabase_auth_user_id', memberIds);
832	    const attendanceUserIds = attendanceUsers?.map(u => u.supabase_auth_user_id) || [];
833	
834	    if(attendanceUserIds.length === 0) return 0;
835	    
836	    const today = toZonedTime(new Date(), timeZone);
837	    const startDate = formatDate(subDays(today, days), 'yyyy-MM-dd');
838	    const endDate = formatDate(today, 'yyyy-MM-dd');
839	
840	    const { data: activityDays, error: activityDaysError } = await supabase
841	        .schema('attendance')
842	        .from('attendances')
843	        .select('date', { count: 'exact' })
844	        .gte('date', startDate)
845	        .lte('date', endDate);
846	
847	    const totalActivityDays = new Set(activityDays?.map(d => d.date)).size;
848	    if (totalActivityDays === 0) return 0;
849	
850	    const { data: teamAttendances, error: teamAttendancesError } = await supabase
851	        .schema('attendance')
852	        .from('attendances')
853	        .select('date, user_id')
854	        .in('user_id', attendanceUserIds)
855	        .eq('type', 'in')
856	        .gte('date', startDate)
857	        .lte('date', endDate);
858	
859	    if (teamAttendancesError || !teamAttendances) return 0;
860	
861	    const dailyAttendanceCount = teamAttendances.reduce((acc, curr) => {
862	        if (!curr.date) return acc;
863	        if (!acc[curr.date]) {
864	            acc[curr.date] = new Set();
865	        }
866	        acc[curr.date].add(curr.user_id);
867	        return acc;
868	    }, {} as Record<string, Set<string>>);
869	    
870	    const dailyRates = Object.values(dailyAttendanceCount).map(users => (users.size / memberIds.length) * 100);
871	    const averageRate = dailyRates.length > 0 ? dailyRates.reduce((sum, rate) => sum + rate, 0) / dailyRates.length : 0;
872	
873	    return averageRate;
874	}
